import {refreshAdminNavigation} from './admin-navigation.mjs';
import {initWelcomeLogin} from './welcome-login.mjs';
import {initMemberNotifications} from './member-notifications.mjs';
import {initHowItWorks} from './how-it-works.mjs';
import {discoverIntro,discoverCommunity,discoveryCard,di} from './discover-design.mjs';
import {remainingSavedCards,savedIdsKey,savedPreviewsKey} from './saved-model.mjs';
let activeUserId='device-preview';
let swipeCount=1,swipeSlots=[];try{const stored=Number(localStorage.getItem('debtfreelately-swipe-count'));if(Number.isInteger(stored)&&stored>=1&&stored<=5)swipeCount=stored;}catch{}
import {showSupportChoices,showSupportMessageStep} from './card-actions.mjs';
import {debtCardHTML,cardDetailsHTML} from './debt-card.mjs';
import {publicCard,defaultPrivacy} from './card-model.mjs';
import {initCardWizard,showCardWizard,startNewDebtCard} from './card-wizard.mjs';
import {initDebts,showDebts,renderDebts} from './debts.mjs';
import {initBrosJoin,showBrosJoin} from './bros-join.mjs';
import {initRegistration,requireRegistration,logoutRegistration} from './registration.mjs';
import {initMessages,showMessages,openCardConversation,openSupporterMessage} from './messages.mjs';
import {initBroke,showBroke as displayBroke,hideBroke} from './broke.mjs';
import {validatePost,commitment,filterPosts} from './model.mjs';
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const samples=[{id:'demo-1',name:'Minh Anh',city:'TP. Hồ Chí Minh',category:'Sinh hoạt',title:'Một khoảng thở để bắt đầu lại.',story:'Sau khi mất việc, mình dùng khoản vay nhỏ để trang trải tiền nhà và sinh hoạt cho hai mẹ con. Mình đã có công việc mới, nhưng khoản nợ cũ vẫn khiến mỗi tháng trở nên chật vật.\n\nMình đang cố gắng từng ngày. Một chút đồng hành lúc này sẽ giúp mình ổn định lại cuộc sống và có thời gian dành cho con.',amount:18500000,pledged:0,sample:true},{id:'demo-2',name:'Hoàng Nam',city:'Đà Nẵng',category:'Y tế',title:'Để ba yên tâm tiếp tục điều trị.',story:'Chi phí điều trị của ba đến bất ngờ, mình phải vay để lo viện phí. Mình đang làm thêm ngoài giờ để trả dần, nhưng vẫn cần một chút giúp đỡ để vượt qua giai đoạn này.',amount:32000000,pledged:0,sample:true},{id:'demo-3',name:'Thu Hà',city:'Hà Nội',category:'Học tập',title:'Mình muốn viết tiếp giấc mơ giảng đường.',story:'Mình là sinh viên năm cuối, vừa học vừa làm để tự trang trải. Khoản vay học phí là điều mình đang lo nhất. Mình mong có thể hoàn thành kỳ học cuối và tìm một công việc ổn định.',amount:12000000,pledged:0,sample:true},{id:'demo-4',name:'Quốc Bảo',city:'Cần Thơ',category:'Sinh hoạt',title:'Dựng lại góc sửa xe nhỏ của mình.',story:'Tiệm sửa xe nhỏ là nguồn thu nhập chính của gia đình. Sau một thời gian phải nghỉ việc vì tai nạn, mình đang quay lại làm và cần giải quyết khoản nợ sinh hoạt tích lại.',amount:9500000,pledged:0,sample:true}];
const initial=()=>({posts:structuredClone(samples),saved:[],skipped:[],pledges:[],role:'Bros'});let state=initial(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('debtfreelately-v1'));if(raw&&Array.isArray(raw.posts)&&Array.isArray(raw.saved)&&Array.isArray(raw.skipped)&&Array.isArray(raw.pledges)){state=raw;state.posts=raw.posts.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&typeof p.title==='string'&&typeof p.story==='string'&&Number.isFinite(p.amount)&&Number.isFinite(p.pledged));}}catch{storageOK=false;}
let approvedPosts=[];
const allPosts=()=>[...state.posts.filter(p=>p.sample||p.mine),...approvedPosts];
let view='discover',category='Tất cả',query='',lastSkipped=null,current=null;const categories=['Tất cả','Sinh hoạt','Y tế','Học tập','Khác'];
function persist(){try{localStorage.setItem('debtfreelately-v1',JSON.stringify(state));return true;}catch{storageOK=false;toast('Không lưu được trên thiết bị. Thay đổi chỉ tồn tại trong phiên này.');return false;}}
let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}function close(){$('#modal').close();}$('#close-modal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
function filtered(){return filterPosts(allPosts(),{category,query,skipped:state.skipped}).filter(p=>!p.mine&&p.pledged<p.amount);}
function empty(title,text,button='',action=''){return `<div class="empty"><div class="symbol">✳</div><h2>${title}</h2><p>${text}</p>${button?`<button class="dark" data-action="${action}">${button}</button>`:''}</div>`;}
function render(){document.body.classList.toggle('swipe-page',view==='discover');document.body.classList.toggle('saved-page',view==='saved');$('#profile-nav').hidden=false;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#saved-count').textContent=state.saved.length+Object.keys(previewStore()).length;$('#role-name').textContent=state.role==='Bros'?'Bạn là một Bros':'Bạn là Broke';$('#categories').innerHTML=categories.map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c}</button>`).join('');$('.toolbar').hidden=view!=='discover'&&view!=='saved';const titles={discover:['Một lần quẹt.<br><span>Một khởi đầu mới.</span>','Phía sau mỗi khoản nợ là một câu chuyện. Lắng nghe, kết nối<br class="desktop"> và giúp ai đó bước tiếp — theo cách của bạn.'],saved:['Những câu chuyện<br><span>bạn muốn giữ lại.</span>','Một kết nối nhỏ hôm nay có thể trở thành sự đồng hành ngày mai.'],pledges:['Sự tử tế,<br><span>được ghi nhận.</span>','Theo dõi cam kết của bạn. Chưa có tiền được chuyển qua ứng dụng.'],mine:['Câu chuyện của bạn.<br><span>Một cơ hội mới.</span>','Chia sẻ điều bạn đang trải qua và quản lý các bài đăng của mình.']};$('#page-title').innerHTML=titles[view][0];$('#page-description').innerHTML=titles[view][1];
if(view==='discover')renderDeck();if(view==='saved')renderSavedCards();if(view==='mine')renderList(state.posts.filter(p=>p.mine),'mine');if(view==='pledges')renderPledges();}
function projectedPost(p){if(p.serverCard)return p.serverCard;const settings=p.privacy||(p.sample?{realName:true,age:true,location:true,photo:true,publicStory:true}:defaultPrivacy());return publicCard([{title:p.title,story:p.story}],settings,{name:p.name,nickname:p.nickname||'Broke_'+p.id.slice(0,6),age:p.age||(p.sample&&p.id==='demo-1'?25:undefined),location:p.city,photo:p.photo||(p.sample&&p.id==='demo-1'?'assets/demo-minh-anh.png':undefined)});}
function renderDeck(){const posts=filtered();const allowed=new Set(posts.map(p=>p.id));swipeSlots=Array.from({length:swipeCount},(_,i)=>allowed.has(swipeSlots[i])?swipeSlots[i]:null);for(let i=0;i<swipeSlots.length;i++)if(!swipeSlots[i])swipeSlots[i]=posts.find(p=>!swipeSlots.includes(p.id))?.id||null;const visible=swipeSlots.map(id=>posts.find(p=>p.id===id)).filter(Boolean);current=visible[0];$('#content').innerHTML=`<div class="discover-layout ${swipeCount>1?"is-multi":""}">${discoverIntro()}<section class="discover-deck"><section class="swipe-stage"><div class="swipe-count-control"><label for="swipe-card-count">Số lượng thẻ quẹt trong một lần<small>Tối đa 5 thẻ · Mỗi người chỉ xuất hiện một lần</small></label><select id="swipe-card-count" aria-label="Số lượng thẻ quẹt trong một lần">${[1,2,3,4,5].map(n=>`<option value="${n}" ${swipeCount===n?'selected':''}>${n} thẻ</option>`).join('')}</select></div>${visible.length?`<div class="swipe-decks" data-count="${swipeCount}">${visible.map(p=>`<div class="deck-swipe" data-card-id="${esc(p.id)}">${discoveryCard(projectedPost(p),{post:p,saved:state.saved.includes(p.id)})}</div>`).join('')}</div><p class="swipe-queue-note">${visible.length<swipeCount?`Còn ${visible.length} thẻ phù hợp để hiển thị. `:''}${swipeCount>1?'Trên điện thoại, vuốt ngang để xem các thẻ đã chọn.':''}</p>`:empty('Bạn đã xem hết rồi!','Xem lại các câu chuyện đã bỏ qua để tiếp tục khám phá.','Xem lại các thẻ','reset')}</section><div class="discover-carousel-footer"><button data-action="undo" aria-label="Quay lại thẻ vừa bỏ qua" ${lastSkipped?'':'disabled'}>‹</button><span>${visible.length} / ${posts.length} câu chuyện</span><button data-action="skip" aria-label="Xem người tiếp theo" ${current?'':'disabled'}>›</button></div></section>${discoverCommunity({stories:allPosts().filter(p=>!p.mine).length,saved:getRemainingSaved().length})}</div>`;$('#swipe-card-count').onchange=event=>{const count=Number(event.target.value);if(!Number.isInteger(count)||count<1||count>5)return;swipeCount=count;try{localStorage.setItem('debtfreelately-swipe-count',String(count));}catch{}renderDeck();};document.querySelectorAll('.swipe-decks .deck-swipe').forEach(card=>{let start=null;card.addEventListener('pointerdown',event=>{if(event.target.closest('button')||(swipeCount>1&&window.matchMedia('(max-width:620px)').matches))return;start={x:event.clientX,y:event.clientY};});card.addEventListener('pointerup',event=>{if(!start)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;start=null;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5){if(dx<0)skip(card.dataset.cardId);else showCardDetails(card.dataset.cardId);}});card.addEventListener('pointercancel',()=>start=null);});}
function previewStore(){try{return JSON.parse(localStorage.getItem(savedPreviewsKey(activeUserId))||'{}');}catch{return {};}}
function cardById(id){if(id.startsWith('preview:'))return previewStore()[id.slice(8)]||null;const p=allPosts().find(p=>p.id===id);return p?projectedPost(p):null;}
function showCardDetails(id){const card=cardById(id);if(!card)return;showSupportChoices({modal,close,pay:()=>showSupportMessageStep({id,name:card.name,modal,toast}),contact:()=>openCardConversation({id,name:card.name,title:card.debts.map(d=>d.title).join(' · ')})});}
function openSavedCards(){document.body.classList.remove('broke-mode','messages-mode','debts-mode','card-wizard-mode');category='Tất cả';query='';view='saved';render();window.scrollTo(0,0);}
function getRemainingSaved(){const cards=[...allPosts().filter(p=>state.saved.includes(p.id)).map(p=>({id:p.id,card:projectedPost(p),sample:p.sample})),...Object.entries(previewStore()).map(([id,card])=>({id:'preview:'+id,card}))];return remainingSavedCards(cards,state.supportTransactions||[],activeUserId);}
function renderSavedCards(){const items=getRemainingSaved();$('#content').innerHTML=items.length?`<section class="saved-only-grid" aria-label="Các thẻ đã lưu chưa được bạn giúp đỡ">${items.map(item=>`<div class="saved-card-item">${debtCardHTML(item.card,{id:item.id,saved:true,sample:item.sample})}</div>`).join('')}</section>`:empty('Chưa có thẻ đang chờ bạn.','Các thẻ đã lưu và chưa được bạn giúp đỡ sẽ xuất hiện tại đây.','Tìm Broke','discover');}
function renderList(posts,kind){if(!posts.length){$('#content').innerHTML=empty(kind==='mine'?'Câu chuyện của bạn bắt đầu ở đây.':'Chưa có câu chuyện nào. ',kind==='mine'?'Đăng bài bằng biệt danh. Không chia sẻ số tài khoản hoặc giấy tờ cá nhân.':'Nhấn ngôi sao trên thẻ để lưu một câu chuyện.',kind==='mine'?'Viết câu chuyện':'Khám phá ngay',kind==='mine'?'new':'discover');return;}$('#content').innerHTML=posts.map(p=>`<article class="list-card"><small>${esc(p.category)} · ${p.sample?'Hồ sơ mẫu':'Chưa xác minh'}</small><h3>${esc(p.title)}</h3><small>${esc(p.name)}</small><div class="row"><strong>${money(p.amount)}</strong><button class="text-button" data-action="detail" data-id="${esc(p.id)}">Xem câu chuyện ↗</button></div><div class="progress"><div style="width:${Math.min(100,p.pledged/p.amount*100)}%"></div></div><small>${money(p.pledged)} cam kết · Chưa thanh toán</small><div class="row">${kind==='mine'?`<button class="text-button" data-action="edit" data-id="${esc(p.id)}">Sửa bài</button><button class="text-button danger" data-action="delete" data-id="${esc(p.id)}">Xóa bài</button>`:`<button class="text-button" data-action="save" data-id="${esc(p.id)}">Bỏ lưu</button><button class="dark" data-action="help" data-id="${esc(p.id)}">Tôi muốn giúp ♡</button>`}</div></article>`).join('');}
function renderPledges(){if(!state.pledges.length){$('#content').innerHTML=empty('Một chút giúp đỡ, một ý nghĩa lớn.','Cam kết bạn xác nhận sẽ xuất hiện ở đây.<br>Đây chưa phải khoản tiền đã gửi.','Tìm câu chuyện','discover');return;}$('#content').innerHTML=`<div class="stats"><div class="stat"><small>Tổng cam kết</small><strong>${money(state.pledges.reduce((s,p)=>s+p.amount,0))}</strong></div><div class="stat"><small>Số lần đồng hành</small><strong>${state.pledges.length}</strong></div></div>`+state.pledges.map(p=>`<article class="list-card"><small>${new Date(p.date).toLocaleDateString('vi-VN')} · Chưa thanh toán</small><h3>${esc(p.title)}</h3><div class="row"><strong>${money(p.amount)}</strong><button class="text-button danger" data-action="cancel" data-id="${esc(p.id)}">Hủy cam kết</button></div></article>`).join('');}
function skip(id=current?.id){if(!id||state.skipped.includes(id))return;lastSkipped=id;state.skipped.push(id);persist();const card=[...document.querySelectorAll('.deck-swipe')].find(c=>c.dataset.cardId===id);card?.classList.add('out-left');setTimeout(render,200);}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];try{localStorage.setItem(savedIdsKey(activeUserId),JSON.stringify(state.saved));}catch{toast('Không lưu được thay đổi trên thiết bị.');}persist();render();}
function detail(id){const p=allPosts().find(p=>p.id===id);if(!p)return;modal(`<div class="eyebrow">${esc(p.category)} · ${p.sample?'HỒ SƠ MẪU':'CHƯA XÁC MINH'}</div><h2>${esc(p.title)}</h2><p>${esc(p.name)} · ${esc(p.city||'Chưa cung cấp địa điểm')}</p><p class="detail-story">${esc(p.story)}</p><div class="info-box">Khoản nợ: <strong>${money(p.amount)}</strong><br>Cam kết: ${money(p.pledged)} · Chưa thanh toán</div>${p.sample?'<p>Câu chuyện minh họa để trải nghiệm ứng dụng, không đại diện cho lời kêu gọi thật.</p>':''}<button class="dark" id="detail-help">${p.mine?'Đóng':'Tôi muốn đồng hành ♡'}</button>`);$('#detail-help').onclick=()=>{close();if(!p.mine)help(id);};}
function help(id){const p=allPosts().find(p=>p.id===id);if(!p)return;const remaining=p.amount-p.pledged;if(remaining<=0){toast('Câu chuyện này đã đủ cam kết.');return;}modal(`<div class="eyebrow">MỘT CHÚT ĐỒNG HÀNH</div><h2>Bạn muốn giúp ${esc(p.name)}?</h2><p>${esc(p.title)}</p><div class="info-box">Còn cần cam kết: <strong>${money(remaining)}</strong><br>${p.sample?'Đây là hồ sơ mẫu. ':''}Chỉ ghi nhận ý định hỗ trợ. Không thu hoặc chuyển tiền.</div><form id="pledge-form"><label for="pledge-amount">Số tiền bạn muốn cam kết (VNĐ)</label><input id="pledge-amount" name="amount" type="number" min="1000" max="${remaining}" step="1000" value="${Math.min(100000,remaining)}" required><div class="form-error" id="form-error" role="alert"></div><button class="dark">Xác nhận cam kết · Chưa thanh toán</button></form>`);$('#pledge-form').onsubmit=e=>{e.preventDefault();try{const amount=Number(new FormData(e.target).get('amount'));const updated=commitment(p,amount);state.posts=state.posts.map(x=>x.id===id?updated:x);state.pledges.push({id:crypto.randomUUID(),postId:id,title:p.title,amount,date:new Date().toISOString()});persist();close();render();toast('Đã ghi nhận cam kết. Chưa có tiền được chuyển.');}catch(error){$('#form-error').textContent=error.message;}};}
function renderPostForm(id){const p=allPosts().find(p=>p.id===id)||{};modal(`<div class="eyebrow">DÀNH CHO BROKE</div><h2>${id?'Chỉnh sửa câu chuyện':'Ai cũng có lúc cần một bàn tay.'}</h2><p>Chia sẻ bằng biệt danh. Bài đăng này chỉ được lưu trên trình duyệt của bạn trong bản thử nghiệm.</p><form id="post-form"><label for="post-name">Tên hiển thị / biệt danh</label><input id="post-name" name="name" maxlength="50" required value="${esc(p.name||'')}"><label for="post-city">Thành phố (không bắt buộc)</label><input id="post-city" name="city" maxlength="60" value="${esc(p.city||'')}"><label for="post-title">Tiêu đề câu chuyện</label><input id="post-title" name="title" maxlength="100" required value="${esc(p.title||'')}"><label for="post-category">Loại khoản nợ</label><select name="category" id="post-category">${categories.slice(1).map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select><label for="post-amount">Tổng khoản nợ (VNĐ)</label><input id="post-amount" name="amount" type="number" min="${Math.max(1000,p.pledged||0)}" max="1000000000000" step="1000" required value="${p.amount||''}"><label for="post-story">Câu chuyện của bạn</label><textarea id="post-story" name="story" maxlength="3000" required placeholder="Điều gì đã xảy ra và sự hỗ trợ sẽ giúp bạn thế nào?">${esc(p.story||'')}</textarea><div class="info-box">Không đăng CCCD, địa chỉ cụ thể, thông tin thẻ hoặc số tài khoản. Chức năng xác minh sẽ được bổ sung sau.</div><div id="form-error" class="form-error" role="alert"></div><button class="dark">${id?'Lưu thay đổi':'Đăng câu chuyện'}</button></form>`);$('#post-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.amount=Number(d.amount);for(const k of ['name','city','title','story'])d[k]=d[k].trim();validatePost(d);if(d.amount<(p.pledged||0))throw Error('Số nợ không thể thấp hơn tổng cam kết.');if(id)state.posts=state.posts.map(x=>x.id===id?{...x,...d}:x);else state.posts.unshift({...d,id:crypto.randomUUID(),pledged:0,mine:true,sample:false});state.role='Broke';persist();view='mine';close();render();toast(id?'Đã lưu thay đổi.':'Đã lưu bài đăng trên thiết bị của bạn.');}catch(error){$('#form-error').textContent=error.message;}};}
function deletePost(id){const p=state.posts.find(p=>p.id===id&&p.mine);if(!p)return;modal(`<h2>Xóa câu chuyện này?</h2><p>${esc(p.title)}</p><p>Bài đăng sẽ bị xóa khỏi thiết bị này.</p><button id="confirm-delete" class="dark">Xóa bài đăng</button>`);$('#confirm-delete').onclick=()=>{state.posts=state.posts.filter(x=>x.id!==id);state.saved=state.saved.filter(x=>x!==id);persist();close();render();toast('Đã xóa bài đăng.');};}
function cancelPledge(id){const p=state.pledges.find(x=>x.id===id);if(!p)return;modal(`<h2>Hủy cam kết ${money(p.amount)}?</h2><p>${esc(p.title)}</p><p>Không có khoản tiền nào cần hoàn trả vì chưa thực hiện thanh toán.</p><button class="dark" id="confirm-cancel">Xác nhận hủy cam kết</button>`);$('#confirm-cancel').onclick=()=>{state.posts=state.posts.map(x=>x.id===p.postId?{...x,pledged:Math.max(0,x.pledged-p.amount)}:x);state.pledges=state.pledges.filter(x=>x.id!==id);persist();close();render();toast('Đã hủy cam kết.');};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-view],[data-category]');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.category){category=b.dataset.category;render();return;}const id=b.dataset.id;switch(b.dataset.action){case 'save':save(id);break;case 'detail':detail(id);break;case 'help':help(id);break;case 'skip':skip();break;case 'reset':state.skipped=[];lastSkipped=null;persist();render();break;case 'undo':if(lastSkipped){state.skipped=state.skipped.filter(x=>x!==lastSkipped);lastSkipped=null;persist();render();}break;case 'discover':view='discover';category='Tất cả';query='';$('#search').value='';render();break;case 'new':postForm();break;case 'edit':postForm(id);break;case 'delete':deletePost(id);break;case 'cancel':cancelPledge(id);}});
$('#search').oninput=e=>{query=e.target.value;render();};$('#new-post').onclick=()=>postForm();$('#role-toggle').onclick=()=>{state.role=state.role==='Bros'?'Broke':'Bros';view=state.role==='Broke'?'mine':'discover';persist();render();};$('#about').onclick=()=>modal(`<div class="eyebrow">WELCOME TO DEBTFREELATELY</div><h2>Cùng nhau nhẹ gánh.</h2><p><strong>Broke</strong> chia sẻ câu chuyện và khoản nợ. <strong>Bros</strong> quẹt thẻ để khám phá, lưu lại hoặc cam kết giúp một phần.</p><p>Quẹt trái để bỏ qua, quẹt phải để mở xác nhận hỗ trợ. Trên máy tính, bạn cũng có thể dùng phím mũi tên.</p><div class="info-box">Bản thử nghiệm: dữ liệu chỉ lưu tại trình duyệt này, chưa đồng bộ giữa người dùng. Không có đăng nhập, xác minh hoặc thanh toán thật. Hồ sơ mẫu được ghi rõ trên thẻ.</div><p>Cam kết có thể hủy trong mục “Cam kết của tôi”. Bài viết có thể sửa hoặc xóa trong “Bài đăng của tôi”.</p>`);
document.addEventListener('keydown',e=>{if(document.body.classList.contains('card-wizard-mode')||document.body.classList.contains('debts-mode')||document.body.classList.contains('bros-join-mode')||document.body.classList.contains('registration-mode')||document.body.classList.contains('messages-mode')||document.body.classList.contains('broke-mode')||document.body.classList.contains('onboarding')||$('#modal').open||e.target.matches('input,textarea,select')||view!=='discover')return;if(e.key==='ArrowLeft'){e.preventDefault();skip();}if(e.key==='ArrowRight'&&current){e.preventDefault();help(current.id);}});render();if(!storageOK)toast('Bộ nhớ trình duyệt không khả dụng; dữ liệu chỉ tồn tại trong phiên này.');
function showWelcome(){void refreshAdminNavigation();document.body.classList.remove('messages-mode','registration-mode','bros-join-mode','debts-mode','card-wizard-mode');hideBroke();document.body.classList.add('onboarding');document.querySelector('[data-role="Broke"]').focus();window.scrollTo(0,0);}
document.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.role==='Broke'){showBroke();return;}if(button.dataset.role==='Bros'){showBros();return;}state.role=button.dataset.role;view=state.role==='Broke'?'mine':'discover';persist();render();document.body.classList.remove('onboarding');window.scrollTo(0,0);document.querySelector('nav .active').focus({preventScroll:true});}));
$('#choose-role').onclick=showWelcome;
$('#role-toggle').onclick=showWelcome;

initBroke({modal,close,toast,supporterMessage:openSupporterMessage,createCard:createDebtCard,discover:()=>{view='discover';category='Tất cả';query='';render();hideBroke();window.scrollTo(0,0);},saved:openSavedCards,logout:logoutRegistration,messages:showMessages,role:showWelcome,post:()=>postForm(),posts:showDebts,getPosts:()=>state.posts.filter(p=>p.mine)});

$('#profile-nav').onclick=openBrokeProfile;
$('#modal').addEventListener('close',()=>{if(document.body.classList.contains('debts-mode'))renderDebts();else if(document.body.classList.contains('broke-mode'))openBrokeProfile();});
initMessages({modal,close,toast,getRole:()=>state.role,role:showWelcome,profile:openBrokeProfile,discover:()=>{view='discover';render();}});
$('#messages-nav').onclick=showMessages;
function showBroke(){requireRegistration(user=>{activateSavedAccount(user.id);state.role='Broke';view='mine';persist();render();showCardWizard(user);});}
initRegistration({back:showWelcome,toast});

function postForm(id){requireRegistration(user=>{state.role='Broke';view='mine';persist();render();if(document.body.classList.contains('debts-mode'))showDebts();else displayBroke(user);renderPostForm(id);});}
function enterBros(user){activateSavedAccount(user.id);state.role='Bros';view='discover';persist();render();hideBroke();document.body.classList.remove('onboarding','registration-mode','bros-join-mode','messages-mode','debts-mode','card-wizard-mode');window.scrollTo(0,0);$('#role-name').textContent=user.name;}
initWelcomeLogin(user=>{
 if(user.role==='Bros'){enterBros(user);return;}
 activateSavedAccount(user.id);
 state.role='Broke';
 view='mine';
 persist();
 render();
 displayBroke(user);
});
function showBros(){showBrosJoin(enterBros);}
initBrosJoin({back:showWelcome,toast,full:callback=>requireRegistration(callback,'Bros')});
$('#logout-nav').onclick=logoutRegistration;
function openBrokeProfile(){const selectedRole=state.role;const open=user=>{activateSavedAccount(user.id);document.body.classList.remove('onboarding','registration-mode','bros-join-mode','messages-mode','debts-mode','card-wizard-mode','swipe-page');state.role=selectedRole;render();displayBroke({...user,role:selectedRole});};if(selectedRole==='Bros'){fetch('/api/auth/me',{credentials:'same-origin'}).then(async response=>{if(!response.ok)throw Error();const {user}=await response.json();open(user);}).catch(()=>showBrosJoin(open));}else requireRegistration(open);}
initDebts({getPosts:()=>state.posts.filter(p=>p.mine),modal,close,profile:openBrokeProfile,messages:showMessages,back:showWelcome,add:()=>postForm(),edit:postForm,remove:deletePost});
initCardWizard({back:showWelcome,profile:openBrokeProfile,debts:showDebts,modal,close,toast,contact:openCardConversation});
document.addEventListener('click',event=>{const b=event.target.closest('#content [data-dc]');if(!b)return;if(b.dataset.dc==='skip'){if(view==='saved')b.closest('.saved-card-item')?.remove();else skip(b.dataset.id);}if(b.dataset.dc==='save'){if(b.dataset.id.startsWith('preview:')){const items=previewStore();delete items[b.dataset.id.slice(8)];try{localStorage.setItem(savedPreviewsKey(activeUserId),JSON.stringify(items));render();}catch{toast('Không lưu được thay đổi.');}}else save(b.dataset.id);}if(b.dataset.dc==='detail')showCardDetails(b.dataset.id);});
$('.user').setAttribute('role','button');$('.user').setAttribute('tabindex','0');$('.user').setAttribute('aria-label','Mở trang cá nhân');
function brosProfile(){openBrokeProfile();}
$('.user').addEventListener('click',event=>{if(!event.target.closest('#role-toggle'))brosProfile();});$('.user').addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target===$('.user')){event.preventDefault();brosProfile();}});
$('.header-brand').addEventListener('click',event=>{event.preventDefault();brosProfile();});

const swipeBack=document.createElement('button');swipeBack.className='swipe-profile-back';swipeBack.textContent='← Quay lại trang cá nhân';swipeBack.onclick=openBrokeProfile;document.querySelector('.main>header').append(swipeBack);



function createDebtCard(){if(state.role==='Bros'){fetch('/api/auth/me',{credentials:'same-origin'}).then(async response=>{if(!response.ok)throw Error();const {user}=await response.json();startNewDebtCard(user);}).catch(()=>showBrosJoin(startNewDebtCard));}else requireRegistration(startNewDebtCard);}


function activateSavedAccount(id){if(!id||activeUserId===id)return;activeUserId=id;try{const key=savedIdsKey(id),legacyOwner=localStorage.getItem('debtfreelately-legacy-saved-owner');if(!legacyOwner&&localStorage.getItem(key)===null){localStorage.setItem(key,JSON.stringify(state.saved));const old=localStorage.getItem('debtfreelately-saved-card-previews');if(old)localStorage.setItem(savedPreviewsKey(id),old);localStorage.setItem('debtfreelately-legacy-saved-owner',id);}state.saved=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(state.saved))state.saved=[];}catch{state.saved=[];toast('Không đọc được danh sách đã lưu của tài khoản.');}}
const discoverNav=document.createElement('nav');discoverNav.className='discover-main-nav';discoverNav.setAttribute('aria-label','Điều hướng khám phá');discoverNav.innerHTML=[['home','Home'],['discover','Discover'],['community','Community'],['debts','My Debts'],['messages','Messages']].map(([action,label])=>`<button data-discover="${action}" class="${action==='discover'?'selected':''}">${di(action)}<span>${label}</span></button>`).join('');discoverNav.insertAdjacentHTML('beforeend','<button data-notifications type="button">♧ <span>Thông báo</span></button>');document.querySelector('.main>header').append(discoverNav);discoverNav.addEventListener('click',event=>{const b=event.target.closest('[data-discover]');if(!b)return;switch(b.dataset.discover){case 'home':openBrokeProfile();break;case 'discover':view='discover';render();break;case 'community':modal(`<div class="eyebrow">OUR COMMUNITY</div><h2>Cùng nhau nhẹ gánh.</h2><p>Hiện có ${allPosts().filter(p=>!p.mine).length} câu chuyện minh họa và ${getRemainingSaved().length} thẻ bạn đã lưu.</p><div class="info-box">Bản thử nghiệm chưa có dữ liệu cộng đồng trực tiếp, xác minh khoản nợ hoặc thanh toán thật.</div>`);break;case 'debts':showDebts();break;case 'messages':showMessages();break;}});


let loadingPublished=false;
async function refreshPublished(){if(loadingPublished)return;loadingPublished=true;try{const r=await fetch('/api/cards',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Không tải được các thẻ đã duyệt.');const {cards}=await r.json();approvedPosts=cards.map(item=>({id:item.id,name:item.card.name,title:item.card.debts.map(d=>d.title).join(' · '),story:item.card.debts.map(d=>d.story||'').join('\n'),amount:item.card.debts.reduce((sum,d)=>sum+d.amount,0),pledged:0,category:'Khác',mine:false,sample:false,approved:true,serverCard:item.card}));if(view==='discover'||view==='saved')render();}catch{approvedPosts=[];if(view==='discover'||view==='saved')render();toast('Chưa tải được thẻ đã duyệt. Vui lòng tải lại trang.');}finally{loadingPublished=false;}}
refreshPublished();
window.addEventListener('focus',refreshPublished);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshPublished();});
setInterval(()=>{if(!document.hidden)refreshPublished();},30000);

initHowItWorks({Broke:showBroke,Bros:showBros});

initMemberNotifications({modal,toast});
